extern void flush_dcache(void);

static int rtl8201fl_flag = 0;
static int ksz8081_flag = 0;
static int sunplus_flag = 0;
static int wch_flag = 0;

void check_sunplus_flag(synopGMACdevice *gmacdev)
{
	u16 phy_data;
	synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, PHY_ID_HI_REG, &phy_data);
	if (phy_data == 0x44) {
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x0100);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x12, 0x4824);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x0200);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x18, 0x0000);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x0600);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x14, 0x708f);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x13, 0xf000);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x15, 0x1530);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x0800);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x18, 0x00bc);
		sunplus_flag = 1;
	}
	else
		sunplus_flag = 0;
}

void check_ksz8081_flag(synopGMACdevice *gmacdev)
{
	u16 phy_data;
	synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, PHY_ID_HI_REG, &phy_data);
	if (phy_data == 0x22) {
		synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, PHY_ID_LOW_REG, &phy_data);
		printk("%s: %x.\n", __func__, phy_data);
		if ((phy_data & 0xfff0) == 0x1550) {
			synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, 0x1f, &phy_data);
			phy_data |= 0x80;
			synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, phy_data);
		}
		ksz8081_flag = 1;
	}
	else
		ksz8081_flag = 0;
}

void check_wch_flag(synopGMACdevice *gmacdev)
{
	u16 id_h, id_l;
	u16 oui_msb, oui_lsb;
	u16 data;

	synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, PHY_ID_HI_REG, &id_h);
	synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, PHY_ID_LOW_REG, &id_l);

	oui_msb = id_h;
	oui_lsb = id_l >> 10;

	if (oui_msb == 0x7371 && oui_lsb == 0x24) {
		printf("find wch eth phy chip, idh : 0x%x, idl : 0x%x\n", id_h, id_l);
		wch_flag = 1;

		// config rmii clk dir
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x7);
		synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 16, &data);
		data = data & ~0x1000;
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 16, data);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x0);

		// ledsel 00
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x7);
		synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, 19, &data);
		data = data & ~0x430;
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 19, data);
		synopGMAC_write_phy_reg((u32 *)gmacdev->MacBase, gmacdev->PhyBase, 0x1f, 0x0);
	}

}

void check_rtl8201fl_flag(synopGMACdevice *gmacdev)
{
	u16 phy_data;

	check_ksz8081_flag(gmacdev);
	if(ksz8081_flag == 1) return;

	check_sunplus_flag(gmacdev);
	if(sunplus_flag == 1) return;

	check_wch_flag(gmacdev);
	if(wch_flag == 1) return;

	synopGMAC_read_phy_reg((u32 *)gmacdev->MacBase,gmacdev->PhyBase, PHY_ID_LOW_REG, &phy_data);

	phy_data = phy_data & 0x000f;

	TR("%s, phy_data: %x.\n", __func__, phy_data);
	if (phy_data > 5)
		rtl8201fl_flag = 1;
	else
		rtl8201fl_flag = 0;
}

